 1→import { useEffect, useRef, type ReactNode } from 'react';
 2→import { SessionContext } from '../hooks/useSessionId';
 3→
 4→export function SessionProvider({ children }: { children: ReactNode }) {
 5→  const sessionIdRef = useRef<string>(crypto.randomUUID());
 6→
 7→  useEffect(() => {
 8→    const sessionId = sessionIdRef.current;
 9→
10→    const interval = setInterval(() => {
11→      fetch('/api/heartbeat', {
12→        method: 'POST',
13→        headers: { 'X-Session-ID': sessionId },
14→        keepalive: true,
15→      }).catch(() => {});
16→    }, 30_000);
17→
18→    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
19→      navigator.sendBeacon(`/api/session/cleanup?session_id=${sessionId}`);
20→      e.preventDefault();
21→      e.returnValue = '';
22→    };
23→
24→    window.addEventListener('beforeunload', handleBeforeUnload);
25→
26→    return () => {
27→      clearInterval(interval);
28→      window.removeEventListener('beforeunload', handleBeforeUnload);
29→    };
30→  }, []);
31→
32→  return (
33→    <SessionContext.Provider value={sessionIdRef.current}>
34→      {children}
35→    </SessionContext.Provider>
36→  );
37→}
