  1→import type { ToolCallResult } from '../types';
  2→
  3→interface AgentCallbacks {
  4→  onTextChunk: (text: string) => void;
  5→  onThinkingDone: () => void;
  6→  onToolCall: (pending: ToolCallResult) => void;
  7→  onToolResult: (result: ToolCallResult) => void;
  8→  onDone: (sessionId: string | null) => void;
  9→  onError: (error: string) => void;
 10→}
 11→
 12→export type { AgentCallbacks };
 13→
 14→async function streamSSE(
 15→  response: Response,
 16→  callbacks: AgentCallbacks,
 17→  signal?: AbortSignal,
 18→): Promise<void> {
 19→  const reader = response.body?.getReader();
 20→  if (!reader) {
 21→    callbacks.onError('No response stream');
 22→    return;
 23→  }
 24→
 25→  try {
 26→    const decoder = new TextDecoder();
 27→    let buffer = '';
 28→
 29→    while (true) {
 30→      const { done, value } = await reader.read();
 31→      if (done) break;
 32→
 33→      buffer += decoder.decode(value, { stream: true });
 34→      const lines = buffer.split('\n');
 35→      buffer = lines.pop() ?? '';
 36→
 37→      let eventType = '';
 38→      for (const line of lines) {
 39→        if (line.startsWith('event: ')) {
 40→          eventType = line.slice(7).trim();
 41→        } else if (line.startsWith('data: ')) {
 42→          const data = line.slice(6);
 43→          try {
 44→            const parsed = JSON.parse(data);
 45→            handleSSEEvent(eventType, parsed, callbacks);
 46→          } catch {
 47→            // Skip malformed JSON
 48→          }
 49→          eventType = '';
 50→        }
 51→      }
 52→    }
 53→  } catch (e: unknown) {
 54→    if (signal?.aborted) return;
 55→    const msg = e instanceof Error ? e.message : 'Connection failed';
 56→    callbacks.onError(msg);
 57→  }
 58→}
 59→
 60→export async function runAgentLoop(
 61→  message: string,
 62→  agentSessionId: string | null,
 63→  callbacks: AgentCallbacks,
 64→  signal?: AbortSignal,
 65→  userSessionId?: string,
 66→): Promise<void> {
 67→  try {
 68→    const response = await fetch('/api/chat', {
 69→      method: 'POST',
 70→      headers: {
 71→        'Content-Type': 'application/json',
 72→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
 73→      },
 74→      body: JSON.stringify({ message, session_id: agentSessionId }),
 75→      signal,
 76→    });
 77→
 78→    if (!response.ok) {
 79→      const errorText = await response.text();
 80→      callbacks.onError(`Server error: ${errorText}`);
 81→      return;
 82→    }
 83→
 84→    await streamSSE(response, callbacks, signal);
 85→  } catch (e: unknown) {
 86→    if (signal?.aborted) return;
 87→    const msg = e instanceof Error ? e.message : 'Connection failed';
 88→    callbacks.onError(msg);
 89→  }
 90→}
 91→
 92→export async function runAgentEditLoop(
 93→  newMessage: string,
 94→  conversationHistory: { role: string; content: string }[],
 95→  callbacks: AgentCallbacks,
 96→  signal?: AbortSignal,
 97→  userSessionId?: string,
 98→): Promise<void> {
 99→  try {
100→    const response = await fetch('/api/chat/edit', {
101→      method: 'POST',
102→      headers: {
103→        'Content-Type': 'application/json',
104→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
105→      },
106→      body: JSON.stringify({
107→        new_message: newMessage,
108→        conversation_history: conversationHistory,
109→      }),
110→      signal,
111→    });
112→
113→    if (!response.ok) {
114→      const errorText = await response.text();
115→      callbacks.onError(`Server error: ${errorText}`);
116→      return;
117→    }
118→
119→    await streamSSE(response, callbacks, signal);
120→  } catch (e: unknown) {
121→    if (signal?.aborted) return;
122→    const msg = e instanceof Error ? e.message : 'Connection failed';
123→    callbacks.onError(msg);
124→  }
125→}
126→
127→function handleSSEEvent(
128→  eventType: string,
129→  data: Record<string, unknown>,
130→  callbacks: AgentCallbacks,
131→) {
132→  switch (eventType) {
133→    case 'thinking':
134→    case 'answer':
135→      callbacks.onTextChunk(data.text as string);
136→      break;
137→    case 'thinking_done':
138→      callbacks.onThinkingDone();
139→      break;
140→    case 'tool_call':
141→      callbacks.onToolCall({
142→        toolCallId: (data.id as string) ?? '',
143→        toolName: (data.name as string) ?? undefined,
144→        sql: (data.sql as string) ?? '',
145→        command: (data.command as string) ?? undefined,
146→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
147→        columns: [],
148→        rows: [],
149→        rowCount: 0,
150→      });
151→      break;
152→    case 'tool_result': {
153→      const result: ToolCallResult = {
154→        toolCallId: (data.id as string) ?? '',
155→        toolName: (data.name as string) ?? undefined,
156→        sql: (data.sql as string) ?? '',
157→        columns: (data.columns as string[]) ?? [],
158→        rows: (data.rows as Record<string, unknown>[]) ?? [],
159→        rowCount: (data.rowCount as number) ?? 0,
160→        error: (data.error as string) ?? undefined,
161→        output: (data.output as string) ?? undefined,
162→        rawContent: (data.content as string) ?? undefined,
163→      };
164→      callbacks.onToolResult(result);
165→      break;
166→    }
167→    case 'done':
168→      callbacks.onDone((data.session_id as string) ?? null);
169→      break;
170→    case 'error':
171→      callbacks.onError((data.message as string) ?? 'Unknown error');
172→      break;
173→  }
174→}
