  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→
 12→function generateId() {
 13→  return Math.random().toString(36).slice(2, 10);
 14→}
 15→
 16→export function AgentProvider({
 17→  children,
 18→  refreshTables,
 19→}: {
 20→  children: ReactNode;
 21→  refreshTables: () => Promise<void>;
 22→}) {
 23→  const userSessionId = useSessionId();
 24→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 25→  const [isStreaming, setIsStreaming] = useState(false);
 26→  const abortRef = useRef<AbortController | null>(null);
 27→  const textBufferRef = useRef('');
 28→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 29→  const assistantIdRef = useRef('');
 30→  const segmentsRef = useRef<ContentSegment[]>([]);
 31→  const currentTextRef = useRef('');
 32→  const sessionIdRef = useRef<string | null>(null);
 33→
 34→  const flushText = useCallback(() => {
 35→    const text = textBufferRef.current;
 36→    if (!text) return;
 37→    const id = assistantIdRef.current;
 38→    currentTextRef.current += text;
 39→    setMessages((prev) =>
 40→      prev.map((m) =>
 41→        m.id === id ? { ...m, content: m.content + text } : m
 42→      )
 43→    );
 44→    textBufferRef.current = '';
 45→  }, []);
 46→
 47→  const sendMessage = useCallback(
 48→    async (text: string) => {
 49→      if (isStreaming) return;
 50→
 51→      const userMsg: ChatMessage = {
 52→        id: generateId(),
 53→        role: 'user',
 54→        content: text,
 55→      };
 56→
 57→      const assistantId = generateId();
 58→      assistantIdRef.current = assistantId;
 59→      const assistantMsg: ChatMessage = {
 60→        id: assistantId,
 61→        role: 'assistant',
 62→        content: '',
 63→        toolCalls: [],
 64→        isStreaming: true,
 65→      };
 66→
 67→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 68→      setIsStreaming(true);
 69→      textBufferRef.current = '';
 70→      segmentsRef.current = [];
 71→      currentTextRef.current = '';
 72→
 73→      const controller = new AbortController();
 74→      abortRef.current = controller;
 75→
 76→      await runAgentLoop(
 77→        text,
 78→        sessionIdRef.current,
 79→        {
 80→          onTextChunk: (chunk) => {
 81→            textBufferRef.current += chunk;
 82→            if (!flushTimerRef.current) {
 83→              flushTimerRef.current = setTimeout(() => {
 84→                flushText();
 85→                flushTimerRef.current = null;
 86→              }, 50);
 87→            }
 88→          },
 89→          onThinkingDone: () => {
 90→            // Extended thinking just ended and a text block is starting.
 91→            // Create a thinking segment from accumulated thinking text.
 92→            if (flushTimerRef.current) {
 93→              clearTimeout(flushTimerRef.current);
 94→              flushTimerRef.current = null;
 95→            }
 96→            flushText();
 97→            if (currentTextRef.current.trim()) {
 98→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
 99→              currentTextRef.current = '';
100→            }
101→            setMessages((prev) =>
102→              prev.map((m) =>
103→                m.id === assistantId
104→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
105→                  : m
106→              )
107→            );
108→          },
109→          onToolCall: (pending: ToolCallResult) => {
110→            if (flushTimerRef.current) {
111→              clearTimeout(flushTimerRef.current);
112→              flushTimerRef.current = null;
113→            }
114→            flushText();
115→            if (currentTextRef.current.trim()) {
116→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
117→              currentTextRef.current = '';
118→            }
119→            // Add a pending tool segment so the input is shown immediately
120→            segmentsRef.current.push({
121→              type: 'tool',
122→              toolResult: pending,
123→            });
124→            setMessages((prev) =>
125→              prev.map((m) =>
126→                m.id === assistantId
127→                  ? { ...m, segments: [...segmentsRef.current] }
128→                  : m
129→              )
130→            );
131→          },
132→          onToolResult: (result: ToolCallResult) => {
133→            // Merge result into pending tool segment (keep input info, add output)
134→            const pendingIdx = segmentsRef.current.findIndex(
135→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
136→            );
137→            if (pendingIdx !== -1) {
138→              const pending = segmentsRef.current[pendingIdx].toolResult!;
139→              segmentsRef.current[pendingIdx] = {
140→                type: 'tool',
141→                toolResult: {
142→                  ...pending,
143→                  ...result,
144→                  toolName: result.toolName || pending.toolName,
145→                  command: result.command || pending.command,
146→                  toolInput: result.toolInput || pending.toolInput,
147→                },
148→              };
149→            } else {
150→              segmentsRef.current.push({ type: 'tool', toolResult: result });
151→            }
152→            setMessages((prev) =>
153→              prev.map((m) =>
154→                m.id === assistantId
155→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
156→                  : m
157→              )
158→            );
159→            refreshTables();
160→          },
161→          onDone: (newSessionId) => {
162→            if (newSessionId) sessionIdRef.current = newSessionId;
163→            if (flushTimerRef.current) {
164→              clearTimeout(flushTimerRef.current);
165→              flushTimerRef.current = null;
166→            }
167→            flushText();
168→            if (currentTextRef.current.trim()) {
169→              segmentsRef.current.push({
170→                type: 'answer',
171→                text: currentTextRef.current,
172→              });
173→              currentTextRef.current = '';
174→            }
175→            setMessages((prev) =>
176→              prev.map((m) =>
177→                m.id === assistantId
178→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
179→                  : m
180→              )
181→            );
182→            setIsStreaming(false);
183→            abortRef.current = null;
184→          },
185→          onError: (error) => {
186→            if (flushTimerRef.current) {
187→              clearTimeout(flushTimerRef.current);
188→              flushTimerRef.current = null;
189→            }
190→            flushText();
191→            setMessages((prev) =>
192→              prev.map((m) =>
193→                m.id === assistantId
194→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
195→                  : m
196→              )
197→            );
198→            setIsStreaming(false);
199→            abortRef.current = null;
200→          },
201→        },
202→        controller.signal,
203→        userSessionId,
204→      );
205→    },
206→    [isStreaming, flushText, refreshTables, userSessionId]
207→  );
208→
209→  const editMessage = useCallback(
210→    async (messageIndex: number, newContent: string) => {
211→      if (isStreaming) return;
212→
213→      // Build conversation history from messages before the edit point
214→      const conversationHistory: { role: string; content: string }[] = [];
215→      for (let i = 0; i < messageIndex; i++) {
216→        const msg = messages[i];
