286→              currentTextRef.current = '';
287→            }
288→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
289→            setMessages((prev) =>
290→              prev.map((m) =>
291→                m.id === assistantId
292→                  ? { ...m, segments: [...segmentsRef.current] }
293→                  : m
294→              )
295→            );
296→          },
297→          onToolResult: (result: ToolCallResult) => {
298→            const pendingIdx = segmentsRef.current.findIndex(
299→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
300→            );
301→            if (pendingIdx !== -1) {
302→              const pending = segmentsRef.current[pendingIdx].toolResult!;
303→              segmentsRef.current[pendingIdx] = {
304→                type: 'tool',
305→                toolResult: {
306→                  ...pending,
307→                  ...result,
